#!/usr/bin/env python3
"""dock/pose_buster_validate — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "dock"
SKILL = "pose_buster_validate"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'pose_buster_validate', 'version': '0.6.5', 'overall_pass': False, 'n_checks': 19, 'n_passed': 17, 'failed_checks': ['intermolecular_steric_clash', 'bond_lengths'], 'per_check': {'mol_pred_loaded': True, 'rdkit_sanitization': True, 'atoms': True, 'bond_lengths': False, 'bond_angles': True, 'internal_steric_clash': True, 'intermolecular_steric_clash': False, 'valence': True, 'kekulization': True, 'geometry': True, 'ring_flat': True, 'double_bond_flat': True, 'amide_planar': True, 'passes_valence_inchi': True, 'passes_kekulization': True, 'passes_geometry': True, 'all_atoms_connected': True, 'stereochemistry': True, 'energy_ratio': True}, 'command': 'python -m posebusters.cli ...', 'runtime_sec': 3.2})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """真 PoseBusters 跑一次:走 host_env=praxis-dock 内的 posebusters 0.6.5。

    输入:receptor_pdb + ligand_sdf_or_pdb;checks_to_run 可选子集(默认 "all")。
    输出:overall_pass / n_checks / n_passed / failed_checks / per_check + diagnostics。
    PRAXIS_SKILL_DRY_HOST=1 时 run_tool 返 mock,这里再 fallback 到一个最小合法 dict。
    """
    import os as _os
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    receptor = payload.get("receptor_pdb") or payload.get("receptor")
    ligand = payload.get("ligand_sdf_or_pdb") or payload.get("ligand")
    checks_to_run = payload.get("checks_to_run") or ["all"]

    if not _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        for label, p in [("receptor_pdb", receptor), ("ligand_sdf_or_pdb", ligand)]:
            if not p or not _os.path.isfile(p):
                return {"ok": False, "error": f"{label} 不存在: {p!r}",
                        "diagnostics": {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE}}

    # posebusters 提供 python API 和 CLI;走 python -c 直接调,把 JSON 吐到 stdout
    script = (
        "import json, sys\n"
        "from posebusters import PoseBusters\n"
        f"checks = {checks_to_run!r}\n"
        "pb = PoseBusters(config='dock' if checks == ['all'] else checks)\n"
        f"df = pb.bust(mol_pred={ligand!r}, mol_cond={receptor!r})\n"
        "row = df.iloc[0].to_dict() if len(df) else {}\n"
        "per_check = {k: bool(v) for k, v in row.items() if isinstance(v, (bool,)) or v in (True, False)}\n"
        "failed = [k for k, v in per_check.items() if v is False]\n"
        "out = {\n"
        "  'per_check': per_check,\n"
        "  'n_checks': len(per_check),\n"
        "  'n_passed': sum(1 for v in per_check.values() if v),\n"
        "  'failed_checks': failed,\n"
        "  'overall_pass': len(failed) == 0,\n"
        "}\n"
        "json.dump(out, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 120)))
    runtime = round(_time.time() - t0, 2)

    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "subprocess": {"cmd": r.get("cmd"), "wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}}
    if r.get("dry"):
        return {"ok": True, "skill_id": SKILL, "version": "0.6.5",
                "overall_pass": True, "n_checks": 0, "n_passed": 0, "failed_checks": [],
                "per_check": {}, "runtime_sec": runtime,
                "diagnostics": {**diagnostics, "dry": True}}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "posebusters 调用失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"posebusters stdout 解析失败: {e}",
                "stdout_head": r["stdout"][:300], "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, "version": "0.6.5",
            **parsed, "runtime_sec": runtime, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
